import {answerCount} from './instrument.mjs';
import {intimateCount,temperament} from './extensions-data.mjs';

const progress=(n,total)=>`<div class="journey-progress"><span>${n===total?'Vyplněno':n?'Rozpracováno':'Zatím nevyplněno'}</span><b>${n} / ${total}</b></div><progress value="${n}" max="${total}" aria-label="${n} z ${total} odpovědí"></progress>`;
const action=(n,total,start,result)=>({href:n===total?result:start,label:n===total?'Zobrazit výsledek':n?'Pokračovat v testu':'Začít test'});
export function testCards(personality,intimacy){
 const p=answerCount(personality),i=intimateCount(intimacy),pa=action(p,50,'#dotaznik','#vysledky'),ia=action(i,38,i?'#intimita-dotaznik':'#intimita','#intimita-vysledky');
 return `<div class="journey-tests"><article class="journey-card personality-card"><div class="journey-card-top"><span class="journey-symbol" aria-hidden="true">✳</span><span class="journey-pill">50 otázek · bez účtu</span></div><span class="eyebrow">POVAHA A TEMPERAMENT</span><h2>Jaký/á obvykle jsi?</h2><p>Pět rozměrů osobnosti a mapa temperamentu z jednoho dotazníku.</p>${progress(p,50)}<a class="button" href="${pa.href}">${pa.label} <span aria-hidden="true">→</span></a><a class="journey-method" href="#podklady">IPIP-50 · český překlad nevalidován ↗</a></article><article class="journey-card intimacy-card"><div class="journey-card-top"><span class="journey-symbol" aria-hidden="true">◎</span><span class="journey-pill">38 položek · dobrovolně · 18+</span></div><span class="eyebrow">INTIMITA A PREFERENCE</span><h2>Co je ti blízké?</h2><p>Vlastní role, podmínky pro intimitu, zájmy a hranice. Nezávisle na povaze.</p>${progress(i,38)}<a class="button secondary" href="${ia.href}">${ia.label} <span aria-hidden="true">→</span></a><a class="journey-method" href="#podklady-intimita">Vlastní sebereflexe · nevalidováno ↗</a></article></div>`;
}
export function startPage(personality,intimacy){
 const p=answerCount(personality),i=intimateCount(intimacy),has=p+i>0;
 return `<section class="wrap journey-home"><div class="journey-heading"><div><span class="eyebrow">OSOBNOSTI / TVŮJ PROSTOR</span><h1>${has?'Pokračuj tam,<br><em>kde jsi skončil/a.</em>':'Začni u sebe.<br><em>Vlastním tempem.</em>'}</h1><p class="lead">Vyber si jednu oblast. Výsledek dostaneš hned v prohlížeči, účet není potřeba.</p></div><div class="journey-orbit" aria-hidden="true"><i></i><i></i><i></i><span>ty.</span></div></div>${has?`<a class="journey-resume" href="#profil"><span><strong>Tvoje rozpracované i hotové výsledky</strong><small>Osobnost ${p}/50 · intimita ${i}/38</small></span><span>Můj profil →</span></a>`:''}${testCards(personality,intimacy)}<a class="journey-compare" href="#porovnani"><span class="journey-pair" aria-hidden="true">A ↔ B</span><span><strong>Máte dva profily? Podívejte se na ně spolu.</strong><small>Shody, rozdíly a otázky k rozhovoru. Stačí partnerův kód a tvoje odpovědi, nebo dva kódy.</small></span><span class="journey-go">Porovnat →</span></a><div class="journey-footnote"><span>Orientační sebepoznání. Žádné diagnózy ani skóre kompatibility.</span><a href="#podklady">Zdroje, výpočty a limity →</a></div></section>`;
}
export const personalCallout='<div class="personal-callout"><div><span class="eyebrow">NOVĚ / OSOBNÍ ROZBOR</span><h2>Co tvoje výsledky znamenají v běžném životě?</h2><p>AI výklad s příklady a otázkami pro vlastní ověření. Dobrovolně, bez účtu.</p></div><a class="button" href="#rozbor">Porozumět výsledku →</a></div>';
export function profileHub(personality,intimacy){
 const p=answerCount(personality),i=intimateCount(intimacy),t=temperament(personality);
 return `<div class="wrap page-head compact-head"><span class="eyebrow">MŮJ PROFIL</span><h1>Všechno tvoje.<br><em>Na jednom místě.</em></h1><p class="lead">Pokračuj v odpovědích, otevři výsledek nebo ho vezmi do porovnání.</p></div><section class="wrap profile-hub">${testCards(personality,intimacy)}${personalCallout}<div class="journey-shortcuts"><a href="#temperament"><span aria-hidden="true">◈</span><strong>Temperament</strong><small>${t.complete?'Otevřít mapu →':'Součást osobnostního testu →'}</small></a><a href="#sdileni"><span aria-hidden="true">▣</span><strong>Obrázky do telefonu</strong><small>Vybrat a stáhnout PNG →</small></a><a href="#porovnani"><span aria-hidden="true">⇄</span><strong>Porovnat s někým</strong><small>Stačí jeho porovnávací kód →</small></a><a href="#ucet"><span aria-hidden="true">↗</span><strong>Účet a sdílecí kód</strong><small>Uložit na server / vrátit se k účtu →</small></a></div><details class="journey-manage"><summary>Upravit nebo smazat odpovědi</summary><div class="actions">${p?'<a href="#dotaznik">Upravit osobnost</a><button class="text-button" data-action="reset" data-scope="personality">Smazat osobnost</button>':''}${i?'<a href="#intimita-dotaznik">Upravit intimní odpovědi</a><button class="text-button" data-action="reset" data-scope="intimacy">Smazat intimní profil</button>':''}<button class="text-button" data-action="reset" data-scope="all">Smazat celý místní profil</button></div><p class="small">Před smazáním se ještě zeptáme. Výsledky na serveru spravuješ zvlášť v <a href="#ucet">Účtu</a>.</p></details></section>`;
}
export function resultActions(kind='personality'){
 return `<nav class="wrap result-shortcuts" aria-label="Co dál s výsledkem"><a href="#profil">← Můj profil</a><a href="${kind==='intimacy'?'#intimita-dotaznik':'#dotaznik'}">Upravit odpovědi</a><a href="#rozbor">Osobní AI rozbor ✧</a><a href="#sdileni">Stáhnout obrázek ↗</a><a href="#porovnani">Porovnat s někým →</a></nav>`;
}
